"\n                        /> -->\n                        <select\n                            v-model=\"section\"\n                            class=\"tw-form-control w-full\"\n                        >\n                            <option value=\"_______\" disabled>\n                                Select Class\n                            </option>\n                            <option\n                                v-for=\"(element, index) in allclasses\"\n                                :key=\"index\"\n                                :value=\"element\"\n                            >\n                                {{ element }}\n                            </option>\n                        </select>\n                        <span\n                            v-if=\"errors.section\"\n                            class=\"text-red-500 text-xs font-semibold\"\n                        >\n                            {{ errors.section[0] }}\n                        </span>\n                    </div>\n                    <div class=\"my-6\">\n                        <a\n                            href=\"#\"\n                            class=\"btn btn-submit blue-bg text-white rounded px-6 py-2\"\n                            @click=\"addSection\"\n                        >\n                            Add Class\n                        </a>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Add Subject Modal -->\n        <!-- <div v-if=\"show === 'subject'\" class=\"hidden modal modal-mask\">\n            <div class=\"modal-wrapper px-4\">\n                <div class=\"modal-container w-full max-w-2xl px-8 mx-auto\">\n                    <div class=\"modal-header flex justify-between items-center\">\n                        <h2>Add New Subject(s)</h2>\n                        <button\n                            class=\"modal-default-button text-2xl py-1\"\n                            @click=\"closeModal\"\n                        >\n                            ×\n                        </button>\n                    </div>\n\n                    <div class=\"modal-body\">\n                        <table class=\"w-full border\">\n                            <thead class=\"bg-gray-300\">\n                                <tr>\n                                    <th class=\"tw-form-label px-3 py-2\">\n                                        Subject Name\n                                        <span class=\"text-red-500\">*</span>\n                                    </th>\n                                    <th class=\"tw-form-label px-3 py-2\">\n                                        Code\n                                    </th>\n                                    <th class=\"tw-form-label px-3 py-2\">\n                                        Type <span class=\"text-red-500\">*</span>\n                                    </th>\n                                    <th class=\"w-20\"></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr\n                                    v-for=\"(sub, k) in subjectoptions\"\n                                    :key=\"k\"\n                                    class=\"border-b\"\n                                >\n                                    <td class=\"p-2\">\n                                        <input\n                                            type=\"text\"\n                                            v-model=\"sub.subject_name\"\n                                            class=\"tw-form-control w-full\"\n                                            placeholder=\"Subject Name\"\n                                        />\n                                    </td>\n                                    <td class=\"p-2\">\n                                        <input\n                                            type=\"text\"\n                                            v-model=\"sub.subject_code\"\n                                            class=\"tw-form-control w-full\"\n                                            placeholder=\"Code\"\n                                        />\n                                    </td>\n                                    <td class=\"p-2\">\n                                        <select\n                                            v-model=\"sub.subject_type\"\n                                            class=\"tw-form-control w-full\"\n                                        >\n                                            <option value=\"\" disabled>\n                                                Select Type\n                                            </option>\n                                            <option value=\"core\">Core</option>\n                                            <option value=\"elective\">\n                                                Elective\n                                            </option>\n                                        </select>\n                                    </td>\n                                    <td class=\"p-2 text-center\">\n                                        <button\n                                            class=\"text-xl text-red-600 hover:text-red-800\"\n                                            @click.prevent=\"removeoption(k)\"\n                                            v-if=\"\n                                                subjectoptions.length > 1 ||\n                                                k > 0\n                                            \"\n                                        >\n                                            −\n                                        </button>\n                                        <button\n                                            v-if=\"\n                                                k === subjectoptions.length - 1\n                                            \"\n                                            class=\"text-xl text-green-600 hover:text-green-800 ml-2\"\n                                            @click.prevent=\"addoption\"\n                                        >\n                                            +\n                                        </button>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n\n                    <div class=\"my-6 flex gap-3\">\n                        <a\n                            href=\"#\"\n                            class=\"btn btn-submit blue-bg text-white rounded px-6 py-2\"\n                            @click=\"addSubject\"\n                        >\n                            Save Subjects\n                        </a>\n                        <a\n                            href=\"#\"\n                            class=\"btn btn-secondary\"\n                            @click=\"closeModal\"\n                            >Cancel</a\n                        >\n                    </div>\n                </div>\n            </div>\n        </div> -->\n    </div>\n</template>\n\n<script>\nexport default {\n    props: [\"url\"],\n\n    data() {\n        return {\n            allclasses: [\n                \"Baby Class\",\n                \"Middle Class\",\n                \"Top Class\",\n                \"Primary 1\",\n                \"Primary 2\",\n                \"Primary 3\",\n                \"Primary 4\",\n                \"Primary 5\",\n                \"Primary 6\",\n                \"Primary 7\",\n                \"Senior 1\",\n                \"Senior 2\",\n                \"Senior 3\",\n                \"Senior 4\",\n                \"Senior 5\",\n                \"Senior 6\",\n            ],\n            academic_year_id: \"\",\n            standard_id: \"\",\n    